import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }


    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[][] rows = new long[n][3];
        long maxA = 0, maxB = 0;
        for (long[] r : rows) {
            for (int k = 0; k < 3; k++) r[k] = nextLong();
            Arrays.sort(r);
            maxA = Math.max(maxA, r[0]);
            maxB = Math.max(maxB, r[1]);
        }
        // Beat everyone: own middle above every minimum, own maximum above every middle.
        int answer = 0;
        for (long[] r : rows) if (r[1] > maxA && r[2] > maxB) answer++;
        System.out.println(answer);
    }
}

