import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}


func main() {
	n := readInt()
	rows := make([][3]int, n)
	maxA, maxB := 0, 0
	for i := range rows {
		r := rows[i][:]
		r[0], r[1], r[2] = readInt(), readInt(), readInt()
		sort.Ints(r)
		maxA = max(maxA, r[0])
		maxB = max(maxB, r[1])
	}
	// Beat everyone: own middle above every minimum, own maximum above every middle.
	answer := 0
	for _, r := range rows {
		if r[1] > maxA && r[2] > maxB {
			answer++
		}
	}
